// nodename: Build Manager Summary
const rows = $input.all().map(item => item.json);

const doneReps    = rows.filter(r => r.status === "done");
const pendingReps = rows.filter(r => r.status !== "done");
const allDone     = pendingReps.length === 0;

function listHtml(items) {
  const lis = items
    .map(r => `<li style="margin-bottom:4px;">${r.rep_name}</li>`)
    .join("");
  return `<ul style="font-family:Arial,sans-serif;font-size:14px;color:#222;padding-left:20px;">${lis}</ul>`;
}

let html = `<p style="font-family:Arial,sans-serif;font-size:15px;color:#222;">Good morning,</p>`;
let subject;

if (allDone) {
  subject = "Daily briefing run complete";
  html += `<p style="font-family:Arial,sans-serif;font-size:15px;color:#222;">Today's pipeline briefings have all been sent successfully.</p>`;
  html += `<p style="font-family:Arial,sans-serif;font-size:15px;color:#222;"><strong>${doneReps.length} Account Managers briefed:</strong></p>`;
  html += listHtml(doneReps);
} else {
  subject = `Action needed - ${pendingReps.length} briefing(s) did not complete`;
  html += `<div style="border-left:4px solid #d32f2f;background:#fdecea;padding:14px 18px;margin:0 0 16px 0;">
    <p style="font-family:Arial,sans-serif;font-size:14px;color:#b71c1c;margin:0;"><strong>Attention:</strong> ${pendingReps.length} of ${rows.length} briefings did not complete and need a rerun.</p>
  </div>`;
  html += `<p style="font-family:Arial,sans-serif;font-size:15px;color:#222;"><strong>Sent (${doneReps.length}):</strong></p>`;
  html += listHtml(doneReps);
  html += `<p style="font-family:Arial,sans-serif;font-size:15px;color:#222;"><strong>Not completed (${pendingReps.length}):</strong></p>`;
  html += listHtml(pendingReps);
}

return [{ json: { allDone, subject, emailHtml: html } }];
